First observe that for every $\alpha,\beta\in\bbF_q^n$ and every $x\in\bbF_q^n$,
\[
    \chi_\alpha(x)\overline{\chi_\beta(x)}
    =
    \omega_p^{\Tr(\inner{\alpha}{x})}
    \omega_p^{-\Tr(\inner{\beta}{x})}
    =
    \omega_p^{\Tr(\inner{\alpha-\beta}{x})}
    =
    \chi_{\alpha-\beta}(x),
\]
where we used the $\bbF_p$-linearity of the trace map.

Now note that  $\ind[x_n = -c_i^{-1} \cdot \sum_{j \in [n]\setminus {i}} c_j \cdot x_{\sigma(j)}]$ evaluates to $1$ for exactly one value of $x_n$. Thus we continue from above and get
\begin{align*}
    \delta(f,g) = 1-\frac{1}{|\bbF|^{n-1}}\sum_{x_1,\dots,x_{n-1} \in \bbF}\frac{1}{|\bbF|} = 1-\frac{1}{|\bbF|} \, .
\end{align*}

Expand the three complex-valued functions into their Fourier expansions:
\begin{align*}
&\bbE_{a,b,x,y}
        \left[\sum_{c\in\bbF_q^\times}
        \fexp{\ff}{ca}(x)\fexp{\ff}{cb}(y)
        \fexp{\ff}{-c}(ax+by)
        \right] \\
&=\bbE_{a,b}\left[\sum_{c\in\bbF_q^\times}
    \sum_{\alpha,\beta,\gamma\in\bbF_q^n}
    \widehat{\fexp{\ff}{ca}}(\alpha)
    \widehat{\fexp{\ff}{cb}}(\beta)
    \widehat{\fexp{\ff}{-c}}(\gamma)
    \bbE_{x,y}\left[
        \chi_\alpha(x)\chi_\beta(y)\chi_\gamma(ax+by)
    \right]
\right].
\end{align*}

As $a,b,c$ range over $\bbF_q^\times$, so do $ca$, $cb$, and $-c$. Hence this equals
\[
    \frac{1}{(q-1)^2}
    \sum_{\eta\in\bbF_q^n}
    \left(\sum_{d\in\bbF_q^\times}
        \widehat{\fexp{\ff}{d}}(d\eta)
    \right)^3
    =\frac{1}{(q-1)^2}\sum_{\eta\in\bbF_q^n}S_\eta(f)^3.
\]

For fixed $a,b\in\bbF_q^\times$, Cauchy-Schwarz and
\cref{lem:parseval-identity} give
\begin{align*}
\abs{\sum_{\alpha\in\bbF_q^n}
        \widehat{\fexp{\ff}{a}}(a\alpha)
        \widehat{\fexp{\ff}{b}}(b\alpha)}
&\le
\left(\sum_{\alpha\in\bbF_q^n}\abs{\widehat{\fexp{\ff}{a}}(a\alpha)}^2\right)^{1/2}
\left(\sum_{\alpha\in\bbF_q^n}\abs{\widehat{\fexp{\ff}{b}}(b\alpha)}^2\right)^{1/2} \\
&=1.
\end{align*}
The equality uses that multiplication by $a$ and by $b$ permutes $\bbF_q^n$, and that
Parseval plus $\abs{\fexp{\ff}{a}(x)}=\abs{\fexp{\ff}{b}(x)}=1$ for every $x$
make both squared $L_2$ norms equal to \(1\).

Using \cref{lem:exact-blr-acceptance} and \cref{lem:second-moment-bound},
\begin{align*}
    \Pr[\BLRVerifier=1]
    &=\frac{1}{q}\left(1+\frac{1}{(q-1)^2}
        \sum_{\alpha\in\bbF_q^n}S_\alpha(f)^3\right) \\
    &\le \frac{1}{q}\left(1+\frac{M}{(q-1)^2}
        \sum_{\alpha\in\bbF_q^n}S_\alpha(f)^2\right) \\
    &\le \frac{1}{q}(1+M) \\
    &=1-\delta(f,\lin).
\end{align*}

Define a group $G$ by the set $X \times A$ with the binary operation
\begin{equation} (x, a) \star (y, b) := \bigl(b^{-1}x + a^{-1}y,\; ab\bigr).
\end{equation}

\emph{Associativity.} For $(x, a), (y, b), (z, c) \in G$,
\begin{align*}
\bigl((x, a) \star (y, b)\bigr) \star (z, c)
&= (b^{-1}x + a^{-1}y,\; ab) \star (z, c) = \bigl(b^{-1}c^{-1}x + a^{-1}c^{-1}y + a^{-1}b^{-1}z,\; abc\bigr),


\end{align*}
and an identical computation gives the same expression for $(x, a) \star \bigl((y, b) \star (z, c)\bigr)$.

Using~\equref{eq:star} and~\equref{eq:Flift-def},
\begin{align*}
F_f\bigl((x,a)\star(y,b)\bigr) &= \sum_{c\in A}\omega^{\Tr\, cab\,f(b^{-1}x + a^{-1}y)} \ket{c}\bra{c}, \\
F_f(x, a)\,F_f(y, b) &= \sum_{c\in A} \omega^{\Tr\, c(af(x) + bf(y))} \ket{c}\bra{c}.
\end{align*}

To compute the expectation, we can split to two cases
\begin{align}
\sum_{c\in A} \omega^{\Tr\, c z} = 
    \begin{cases}
        q-1, \quad z=0 \quad \text{when $f$ passes BLR}, \\
        -1, \quad z \neq 0 \quad \text{when $f$ fails BLR}.
    \end{cases}
\end{align}
The second case is because $\sum_{c\in A} \omega^{\Tr\, c z} + 1= \sum_{c\in \FF_q} \omega^{\Tr\, c z} =0$.

Therefore the Fourier coefficients of $F_f$ are
    \begin{align}
        \hat{F}_f(\chi_{\alpha, k}) 
        & = \sum_{c \in \FF_q^\times } \EE_{x, a} \omega^{\Tr\, c a f(x)} \bar{\chi}_{\alpha, k}(x, a) , \nonumber \\
        & = \sum_{c \in \FF_q^\times }\EE_{x,a} \left[ \omega^{\Tr\, a(cf(x) - \langle \alpha, x \rangle)} \overline{\psi_k(a)} \right] \ket{c}\bra{c}.
    \end{align}

Substituting these into the expectation isolates the $c$-dependence: 
\begin{align} 
    [\hat{F}_f(\chi_{c\beta, k})]_{cc} &= \EE_{x,b} \left[ \omega^{\Tr b(f(x) - \langle \beta, x \rangle)} \overline{\psi_k(b)}\psi_k(c) \right] \nonumber \\
    &= \psi_k(c) \nu_k(\beta), 
\end{align}
where $\nu_k(\beta) := \EE_{x,b} \left[ \omega^{\Tr b(f(x) - \langle \beta, x \rangle)} \overline{\psi_k(b)} \right]$ is a $c$-independent coefficient.

Because $F_f$ is diagonal and $\sigma = \I/(q-1)$, the trace equates to the average over the diagonal elements. 
By an intermediate statement in the proof of Gowers-Hatami theorem using Lemma.~\ref{gowers-hatami-correlation}, the compression from an exact representation can be rewritten as a pair-correlation:
\begin{equation}
    \mathcal{C}(f) := \EE_{g,h} \Re \inner{F_f(g) F_f(h)}{F_f(gh)}_\sigma \ge 1 - \epsilon. \end{equation}

To connect the operator pair-correlation directly to the cubic trace of the Fourier coefficients, we express the lift matrices using the inverse Fourier transform, $F_f(x) = \sum_{\chi \in \widehat{G}} \hat{F}_f(\chi) \chi(x)$. Substituting this into the inner product definition of the pair-correlation and using the character homomorphism $\chi(gh) = \chi(g)\chi(h)$, we expand the trace:
\begin{align}
    \mathcal{C}(f) &= \EE_{g,h \in G} \Re \Tr\left( F_f(g)^* F_f(h)^* F_f(gh) \sigma \right) \nonumber \\
    &= \Re \Tr \left( \sum_{\chi_1, \chi_2, \chi_3} \hat{F}_f^*(\chi_1) \hat{F}_f^*(\chi_2) \hat{F}_f(\chi_3) \sigma \cdot \EE_g\left[\overline{\chi_1(g)}\chi_3(g)\right] \EE_h\left[\overline{\chi_2(h)}\chi_3(h)\right] \right).
\end{align}

By the orthogonality of characters, the expectations over $g$ and $h$ independently vanish unless $\chi_1 = \chi_3$ and $\chi_2 = \chi_3$. This completely collapses the triple sum to a single sum over $\chi$. Because the Fourier coefficients of the diagonal lift $F_f$ are themselves diagonal matrices (and thus commute), we can rearrange the surviving terms to recover the exact cubic trace expression:
\begin{equation}
    \mathcal{C}(f) = \Re \sum_{\chi \in \widehat{G}} \Tr\left( \hat{F}_f^*(\chi) \hat{F}_f(\chi) \hat{F}_f^*(\chi) \sigma \right).
\end{equation}

Moreover, because the Fourier coefficients sum to identity by unitarity of $F_f$, we have
    \begin{align}
        1& = \frac{1}{q-1}\sum_{\chi\in\hat{G}}\Tr\left[\hat{F}^*_f(\chi)\hat{F}_f(\chi)\right] , \nonumber \\
        &= \frac{1}{q-1}\sum_{c \in \FF_q^\times} \sum_{\beta \in \FF_q^n} \sum_k |\psi_k(c)\nu_k(\beta)|^2, \nonumber \\
        &= \sum_{\beta \in \FF_q^n} \sum_k |\nu_k(\beta)|^2.
    \end{align}

\emph{Soundness:} If \(Mb \neq c\), then 
\begin{gather*}
  \Pr_{r\leftarrow \F^m} \left[\langle b, u \rangle =  \langle c , r\rangle \right] = \Pr_{r\leftarrow \F^m} \left[\langle Mb, r \rangle =  \langle c , r\rangle \right] 
  \\= \Pr_{r\leftarrow \F^m} \left[ \sum_{i=1}^{m} (Mb - c)_{i} \cdot r_{i} =  0\right] \leq 1 / |\F|,
\end{gather*}
where the last inequality follows from \ref{LINEQ.linear_form_uniform_prob_mul_card_le_one}.
